359	+/**
360	+ * The minimap's fog (§3): every tile starts hidden, and tiles within the sight radius of the player's ship are
361	+ * revealed for good as it sails. Terrain is public content, so this is presentation only, not a security boundary
362	+ * (§16); ships are filtered by the server.
363	+ */
364	+export class FogOfWar {
365	+  private readonly revealed: Uint8Array;
366	+  private count = 0;
367	+  private lastTile = -1;
368	+
369	+  constructor(
370	+    readonly widthTiles: number,
371	+    readonly heightTiles: number,
372	+    readonly radiusTiles: number,
373	+  ) {
374	+    this.revealed = new Uint8Array(widthTiles * heightTiles);
375	+  }
376	+
377	+  get revealedCount(): number {
378	+    return this.count;
379	+  }
380	+
381	+  isRevealed(tileX: number, tileY: number): boolean {
382	+    return this.revealed[tileY * this.widthTiles + tileX] === 1;
383	+  }
384	+
385	+  /** Reveals the disc around a tile and returns the tiles it newly revealed, as `[tileX, tileY]` pairs. */
386	+  revealAround(tileX: number, tileY: number): [number, number][] {
387	+    const centre = tileY * this.widthTiles + tileX;
388	+    if (centre === this.lastTile) return [];
389	+    this.lastTile = centre;
390	+    const fresh: [number, number][] = [];
391	+    const radius = this.radiusTiles;
392	+    for (let dy = -radius; dy <= radius; dy++) {
393	+      for (let dx = -radius; dx <= radius; dx++) {
394	+        if (dx * dx + dy * dy > radius * radius) continue;
395	+        const x = tileX + dx;
396	+        const y = tileY + dy;
397	+        if (x < 0 || y < 0 || x >= this.widthTiles || y >= this.heightTiles) continue;
398	+        const index = y * this.widthTiles + x;
399	+        if (this.revealed[index] === 1) continue;
400	+        this.revealed[index] = 1;
401	+        this.count++;
402	+        fresh.push([x, y]);
403	+      }
404	+    }
405	+    return fresh;
406	+  }
407	+}
