2398	+/**
2399	+ * The sea is a bounded rectangle of tiles laid out like screen coordinates: origin (0,0) at the top-left, x grows
2400	+ * right and y grows down. Every tile is split into a fixed integer number of sub-units, and all positions and speeds
2401	+ * in the simulation are integer sub-units.
2402	+ */
2403	+export const SUB_UNITS_PER_TILE = 256;
2404	+
2405	+/** What a tile is. Sea and docks are navigable; land and shoals stop ships. */
2406	+export const Terrain = {
2407	+  Sea: 0,
2408	+  Land: 1,
2409	+  Shoal: 2,
2410	+  Dock: 3,
2411	+} as const;
2412	+export type Terrain = (typeof Terrain)[keyof typeof Terrain];
2413	+
2414	+/** One character per tile in a map's rows. */
2415	+export const TERRAIN_CHARS: Readonly<Record<string, Terrain>> = {
2416	+  ".": Terrain.Sea,
2417	+  "#": Terrain.Land,
2418	+  "%": Terrain.Shoal,
2419	+  D: Terrain.Dock,
2420	+};
2421	+
2422	+export const ISLAND_THEMES = ["tropical", "volcanic", "ruin", "mist"] as const;
2423	+export type IslandTheme = (typeof ISLAND_THEMES)[number];
2424	+
2425	+/** Eight compass directions, as authored on spawn objects. */
2426	+export const COMPASS = ["E", "SE", "S", "SW", "W", "NW", "N", "NE"] as const;
2427	+export type Compass = (typeof COMPASS)[number];
2428	+
2429	+/** Ship headings are integers in [0, HEADING_COUNT): 0 is east, counting clockwise because y grows down. */
2430	+export const HEADING_COUNT = 64;
2431	+
2432	+export function compassHeading(direction: Compass): number {
2433	+  return COMPASS.indexOf(direction) * (HEADING_COUNT / COMPASS.length);
2434	+}
2435	+
2436	+/** An island as authored: a name, a theme and the tile rectangle holding its land and docks. */
2437	+export interface IslandSource {
2438	+  readonly name: string;
2439	+  readonly theme: IslandTheme;
2440	+  readonly tileX: number;
2441	+  readonly tileY: number;
2442	+  readonly widthTiles: number;
2443	+  readonly heightTiles: number;
2444	+}
2445	+
