2453	+/** A map as the converter writes it (`scripts/build-map.ts`): rows of terrain characters plus the named objects. */
2454	+export interface SeaMapSource {
2455	+  readonly name: string;
2456	+  readonly widthTiles: number;
2457	+  readonly heightTiles: number;
2458	+  readonly rows: readonly string[];
