2473	+/** A decoded map, as the simulation and the client read it. */
2474	+export interface SeaMapDefinition {
2475	+  readonly name: string;
2476	+  readonly widthTiles: number;
2477	+  readonly heightTiles: number;
2478	+  readonly subUnitsPerTile: number;
2479	+  /** Row-major terrain, `widthTiles * heightTiles` entries. */
2480	+  readonly terrain: readonly Terrain[];
2481	+  readonly islands: readonly IslandSource[];
2482	+  /** Row-major order of their tiles. */
2483	+  readonly docks: readonly Dock[];
