2486	+
2487	+/** Decodes a map source. Throws on a structural error (a row of the wrong length, an unknown character). */
2488	+export function createSeaMap(source: SeaMapSource): SeaMapDefinition {
2489	+  if (source.rows.length !== source.heightTiles) {
2490	+    throw new Error(`${source.name}: ${source.rows.length} rows for a height of ${source.heightTiles}`);
2491	+  }
2492	+  const terrain: Terrain[] = [];
2493	+  source.rows.forEach((row, tileY) => {
2494	+    if (row.length !== source.widthTiles) throw new Error(`${source.name}: row ${tileY} has ${row.length} tiles, not ${source.widthTiles}`);
2495	+    for (const char of row) {
2496	+      const kind = TERRAIN_CHARS[char];
2497	+      if (kind === undefined) throw new Error(`${source.name}: unknown terrain "${char}" in row ${tileY}`);
2498	+      terrain.push(kind);
2499	+    }
2500	+  });
2501	+  const docks: Dock[] = [];
2502	+  terrain.forEach((kind, index) => {
2503	+    if (kind !== Terrain.Dock) return;
2504	+    const tileX = index % source.widthTiles;
2505	+    const tileY = Math.floor(index / source.widthTiles);
2506	+    const island = source.islands.findIndex((candidate) => insideIsland(candidate, tileX, tileY));
2507	+    const side = island < 0 ? "N" : sideOf(source.islands[island]!, tileX, tileY);
2508	+    docks.push({ id: docks.length, tileX, tileY, island, side });
2509	+  });
2510	+  return {
2511	+    name: source.name,
2512	+    widthTiles: source.widthTiles,
2513	+    heightTiles: source.heightTiles,
2514	+    subUnitsPerTile: SUB_UNITS_PER_TILE,
2515	+    terrain,
2516	+    islands: source.islands,
2517	+    docks,
2518	+    spawnSlots: source.spawnSlots,
2519	+  };
2520	+}
2521	+
2522	+export function insideIsland(island: IslandSource, tileX: number, tileY: number): boolean {
2523	+  return (
2524	+    tileX >= island.tileX && tileX < island.tileX + island.widthTiles && tileY >= island.tileY && tileY < island.tileY + island.heightTiles
2525	+  );
2526	+}
2527	+
2528	+/** The side of an island a tile lies on (N, E, S or W), from its offset to the island rectangle's centre. */
2529	+function sideOf(island: IslandSource, tileX: number, tileY: number): Compass {
2530	+  // Doubled offsets keep the rectangle's centre on an integer; scaling by the other side's length makes a long thin
2531	+  // island still read its ends as its ends.
2532	+  const dx = (2 * tileX + 1 - (2 * island.tileX + island.widthTiles)) * island.heightTiles;
2533	+  const dy = (2 * tileY + 1 - (2 * island.tileY + island.heightTiles)) * island.widthTiles;
2534	+  if (Math.abs(dx) >= Math.abs(dy)) return dx > 0 ? "E" : "W";
2535	+  return dy > 0 ? "S" : "N";
2536	+}
2537	+
2538	+export function terrainAt(map: SeaMapDefinition, tileX: number, tileY: number): Terrain | undefined {
2539	+  if (tileX < 0 || tileY < 0 || tileX >= map.widthTiles || tileY >= map.heightTiles) return undefined;
2540	+  return map.terrain[tileY * map.widthTiles + tileX];
2541	+}
2542	+
2543	+/** Ships sail on sea and docks. Anything outside the map counts as blocked. */
2544	+export function isNavigable(map: SeaMapDefinition, tileX: number, tileY: number): boolean {
2545	+  const kind = terrainAt(map, tileX, tileY);
2546	+  return kind === Terrain.Sea || kind === Terrain.Dock;
2547	+}
2548	+
2549	+/** A readable name for a dock, for the HUD: "Palm Key, south dock". */
2550	+export function dockLabel(map: SeaMapDefinition, dockId: number): string {
2551	+  const dock = map.docks[dockId];
2552	+  if (dock === undefined) return "";
2553	+  const names: Record<Compass, string> = { E: "east", SE: "south-east", S: "south", SW: "south-west", W: "west", NW: "north-west", N: "north", NE: "north-east" };
