2580	+/**
2581	+ * Shortest sea-path cost in sub-units from one tile to every tile, over navigable tiles, moving in eight directions.
2582	+ * A diagonal step needs both tiles beside it free, since a hull cannot squeeze between two blocked corners.
2583	+ */
2584	+export function seaPathCosts(map: SeaMapDefinition, fromX: number, fromY: number): Float64Array {
2585	+  const width = map.widthTiles;
2586	+  const costs = new Float64Array(width * map.heightTiles).fill(UNREACHABLE);
2587	+  if (!isNavigable(map, fromX, fromY)) return costs;
2588	+  const heap = new MinHeap();
2589	+  const start = fromY * width + fromX;
2590	+  costs[start] = 0;
2591	+  heap.push(0, start);
2592	+  while (heap.size > 0) {
2593	+    const [cost, index] = heap.pop();
2594	+    if (cost > costs[index]!) continue;
2595	+    const x = index % width;
2596	+    const y = (index - x) / width;
2597	+    for (let dy = -1; dy <= 1; dy++) {
2598	+      for (let dx = -1; dx <= 1; dx++) {
2599	+        if (dx === 0 && dy === 0) continue;
2600	+        const nx = x + dx;
