2602	+        if (!isNavigable(map, nx, ny)) continue;
2603	+        const diagonal = dx !== 0 && dy !== 0;
2604	+        if (diagonal && (!isNavigable(map, x + dx, y) || !isNavigable(map, x, y + dy))) continue;
2605	+        const next = cost + (diagonal ? DIAGONAL_COST : STRAIGHT_COST);
2606	+        const target = ny * width + nx;
2607	+        if (next < costs[target]!) {
2608	+          costs[target] = next;
2609	+          heap.push(next, target);
2610	+        }
2611	+      }
2612	+    }
2613	+  }
2614	+  return costs;
2615	+}
