3240	+/**
3241	+ * cos(2π·i/64)·1024 rounded, for the first quarter turn (i = 0…16). Written out as data so that no floating-point
3242	+ * transcendental function runs in the simulation; the other three quarters follow by symmetry.
3243	+ */
3244	+const QUARTER_COSINES: readonly number[] = [1024, 1019, 1004, 980, 946, 903, 851, 792, 724, 650, 569, 483, 392, 297, 200, 100, 0];
3245	+
3246	+const QUARTER = HEADING_COUNT / 4;
3247	+
3248	+function cosine(heading: number): number {
3249	+  const turn = normalizeHeading(heading);
3250	+  if (turn <= QUARTER) return QUARTER_COSINES[turn]!;
3251	+  // Subtracting from 0 rather than negating keeps the table free of -0.
3252	+  if (turn <= 2 * QUARTER) return 0 - QUARTER_COSINES[2 * QUARTER - turn]!;
3253	+  if (turn <= 3 * QUARTER) return 0 - QUARTER_COSINES[turn - 2 * QUARTER]!;
3254	+  return QUARTER_COSINES[HEADING_COUNT - turn]!;
3255	+}
3256	+
3257	+/** Heading components: DX[h], DY[h]. Heading 0 is east; y grows down, so headings count clockwise on screen. */
3258	+export const HEADING_DX: readonly number[] = Array.from({ length: HEADING_COUNT }, (_, heading) => cosine(heading));
3259	+export const HEADING_DY: readonly number[] = Array.from({ length: HEADING_COUNT }, (_, heading) => cosine(heading - QUARTER));
3260	+
3261	+export function normalizeHeading(heading: number): number {
3262	+  return ((heading % HEADING_COUNT) + HEADING_COUNT) % HEADING_COUNT;
