1	import { compassHeading, isNavigable } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { normalizeHeading } from "./heading.js";
4	import { nextInt } from "./random.js";
5	
6	/** 60 fixed steps per second: the one match clock (§15). */
7	export const STEPS_PER_SECOND = 60;
8	/** World logic runs on every third step, 20 times a second (§15). */
9	export const WORLD_STEP_INTERVAL = 3;
10	
11	/** `dock` of a ship at sea. */
12	export const NOT_DOCKED = -1;
13	
14	/** A ship on the sea. Every number is an integer; positions are in sub-units. */
15	export interface ShipState {
16	  readonly id: string;
17	  readonly slot: number;
18	  readonly x: number;
19	  readonly y: number;
20	  /** One of HEADING_COUNT directions: 0 is east, counting clockwise because y grows down. */
21	  readonly heading: number;
22	  /** Sub-units per world step along the heading; negative when reversing. */
23	  readonly speed: number;
24	  /** The id of the dock the ship is moored at, or NOT_DOCKED. */
25	  readonly dock: number;
26	}
27	
28	/** The complete match state: plain, serializable data that `hashState` covers entirely. */
29	export interface MatchState {
30	  /** Steps completed on the 60 Hz match clock. */
31	  readonly frame: number;
32	  /** World steps completed (every third frame). */
33	  readonly worldTick: number;
34	  /** The seeded generator's state. */
35	  readonly rng: number;
36	  /** In join order. */
37	  readonly ships: readonly ShipState[];
38	}
39	
40	export function createMatchState(seed: number): MatchState {
41	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
42	  return { frame: 0, worldTick: 0, rng: seed >>> 0, ships: [] };
43	}
44	
45	/** The centre of a tile, in sub-units. */
46	export function tileCentre(config: SimulationConfig, tileX: number, tileY: number): { x: number; y: number } {
47	  const size = config.map.subUnitsPerTile;
48	  const half = Math.floor(size / 2);
49	  return { x: tileX * size + half, y: tileY * size + half };
50	}
51	
52	/** Adds a ship at rest on a random free spawn slot, facing the slot's heading. Two ships never share a slot. */
53	export function addShip(config: SimulationConfig, state: MatchState, id: string): MatchState {
54	  if (state.ships.some((ship) => ship.id === id)) throw new Error(`ship ${id} already exists`);
55	  const taken = new Set(state.ships.map((ship) => ship.slot));
56	  const free = config.spawnSlots.map((_, index) => index).filter((index) => !taken.has(index));
57	  if (free.length === 0) throw new Error("no free spawn slot");
58	  const drawn = nextInt(state.rng, free.length);
59	  const slot = free[drawn.value]!;
60	  const spawn = config.spawnSlots[slot]!;
61	  const ship: ShipState = {
62	    id,
63	    slot,
64	    ...tileCentre(config, spawn.tileX, spawn.tileY),
65	    heading: compassHeading(spawn.facing),
66	    speed: 0,
67	    dock: NOT_DOCKED,
68	  };
69	  return { ...state, rng: drawn.state, ships: [...state.ships, ship] };
70	}
71	
72	export function removeShip(state: MatchState, id: string): MatchState {
73	  return { ...state, ships: state.ships.filter((ship) => ship.id !== id) };
74	}
75	
76	export interface Placement {
77	  readonly tileX: number;
78	  readonly tileY: number;
79	  readonly heading: number;
80	}
81	
