38	/** Replays an input log: each entry becomes that ship's held input from its frame on. */
39	function run(initial: MatchState, log: readonly LoggedInput[], steps: number, stepConfig: SimulationConfig = config): MatchState {
40	  let state = initial;
41	  const held: Record<string, PlayerInput> = {};
42	  for (let index = 0; index < steps; index++) {
43	    const frame = state.frame + 1;
44	    for (const entry of log) if (entry.frame === frame) held[entry.shipId] = entry.input;
45	    state = step(stepConfig, state, held);
46	  }
47	  return state;
48	}
