63	/** Runs one ship through `worldSteps` world steps with a fixed input, returning every intermediate ship. */
64	function sailFor(ship: ShipState, input: PlayerInput, worldSteps: number, sailConfig: SimulationConfig = config): ShipState[] {
65	  const trail: ShipState[] = [];
66	  let current = ship;
67	  for (let index = 0; index < worldSteps; index++) trail.push((current = sail(sailConfig, current, input)));
68	  return trail;
69	}
